# ---------------- reservation tables & collision bookkeeping -----------------
@njit(cache=True)
def move_dir(nbr, u, v):
    for k in range(1, 5):
        if nbr[u, k] == v:
            return k
    return 0

@njit(cache=True)
def table_update(P, a, occ, eout, nbr, T, sign):
    for t in range(T + 1):
        occ[t, P[t, a]] += sign
    for t in range(T):
        u = P[t, a]; v = P[t + 1, a]
        if u != v:
            k = move_dir(nbr, u, v)
            eout[t, u, k - 1] += sign

@njit(cache=True)
def find_partners(P, a, occ, eout, nbr, T, mark, out):
    """Agents in collision (vertex or swap) with agent a. occ/eout must include a. Returns count."""
    N = P.shape[1]
    cnt = 0
    for t in range(T + 1):
        v = P[t, a]
        if occ[t, v] > 1:
            for b in range(N):
                if b != a and P[t, b] == v and mark[b] == 0:
                    mark[b] = 1; out[cnt] = b; cnt += 1
    for t in range(T):
        u = P[t, a]; v = P[t + 1, a]
        if u != v:
            k = move_dir(nbr, u, v)
            sl = k if (k % 2 == 1) else (k - 2)
            if eout[t, v, sl] > 0:
                for b in range(N):
                    if b != a and P[t, b] == v and P[t + 1, b] == u and mark[b] == 0:
                        mark[b] = 1; out[cnt] = b; cnt += 1
    for i in range(cnt):
        mark[out[i]] = 0
    return cnt

@njit(cache=True)
def detach(S, coll, deg):
    """remove all collision pairs incident to agents in S; return number removed"""
    N = coll.shape[0]; rem = 0
    for i in range(S.shape[0]):
        a = S[i]
        if deg[a] == 0:
            continue
        for b in range(N):
            if coll[a, b]:
                coll[a, b] = 0; coll[b, a] = 0; deg[a] -= 1; deg[b] -= 1; rem += 1
    return rem

@njit(cache=True)
def attach(S, P, occ, eout, nbr, T, coll, deg, mark, buf):
    add = 0
    for i in range(S.shape[0]):
        a = S[i]
        c = find_partners(P, a, occ, eout, nbr, T, mark, buf)
        for j in range(c):
            b = buf[j]
            if not coll[a, b]:
